//! UTF-8 -> ISO/IEC 8859-2 (Latin-2) transcoding helper.
//!
//! This is a small companion to main.zig: qrcodegen.zig's `qrcodegen_encodeIso88592()`
//! only packs bytes and emits the ECI designator, it never transcodes text.
//! Zig string literals and most runtime strings are UTF-8, so anything with
//! Latin-2-only characters (e.g. Polish, Czech, Slovak, Hungarian diacritics)
//! needs converting to single-byte Latin-2 codepoints before being handed to
//! `qrcodegen_encodeIso88592()`, or a compliant decoder will read the raw UTF-8
//! bytes as mismatched Latin-2 characters (mojibake) instead of the intended text.

const std = @import("std");

/// Converts UTF-8 encoded `text` into ISO/IEC 8859-2 bytes, written into `out`,
/// therefore returns the written slice (a prefix of `out`).
///
/// Errors:
/// * `error.InvalidUtf8` if `text` is not valid UTF-8
/// * `error.UnsupportedCharacter` if `text` contains a codepoint with no
///   Latin-2 representation (e.g. emoji, Cyrillic, CJK, curly quotes)
/// * `error.NoSpaceLeft` if `out` is smaller than the converted length
pub fn utf8ToIso88592(text: []const u8, out: []u8) ![]u8 {
	var outLen: usize = 0;
	const view = try std.unicode.Utf8View.init(text);
	var it = view.iterator();
	while (it.nextCodepoint()) |cp| {
		const byte: u8 = if (cp < 0x80)
			@intCast(cp)
		else
			latin2ByteFromCodepoint(cp) orelse return error.UnsupportedCharacter;
		if (outLen >= out.len) return error.NoSpaceLeft;
		out[outLen] = byte;
		outLen += 1;
	}
	return out[0..outLen];
}

/// Maps a Unicode codepoint (`0x80` and above) to its ISO/IEC 8859-2 byte value,
/// or returns null if the codepoint has no Latin-2 representation.
fn latin2ByteFromCodepoint(cp: u21) ?u8 {
	return switch (cp) {
		0x00A0 => 0xA0,
		0x00A4 => 0xA4,
		0x00A7 => 0xA7,
		0x00A8 => 0xA8,
		0x00AD => 0xAD,
		0x00B0 => 0xB0,
		0x00B4 => 0xB4,
		0x00B8 => 0xB8,
		0x00C1 => 0xC1,
		0x00C2 => 0xC2,
		0x00C4 => 0xC4,
		0x00C7 => 0xC7,
		0x00C9 => 0xC9,
		0x00CB => 0xCB,
		0x00CD => 0xCD,
		0x00CE => 0xCE,
		0x00D3 => 0xD3,
		0x00D4 => 0xD4,
		0x00D6 => 0xD6,
		0x00D7 => 0xD7,
		0x00DA => 0xDA,
		0x00DC => 0xDC,
		0x00DD => 0xDD,
		0x00DF => 0xDF,
		0x00E1 => 0xE1,
		0x00E2 => 0xE2,
		0x00E4 => 0xE4,
		0x00E7 => 0xE7,
		0x00E9 => 0xE9,
		0x00EB => 0xEB,
		0x00ED => 0xED,
		0x00EE => 0xEE,
		0x00F3 => 0xF3,
		0x00F4 => 0xF4,
		0x00F6 => 0xF6,
		0x00F7 => 0xF7,
		0x00FA => 0xFA,
		0x00FC => 0xFC,
		0x00FD => 0xFD,
		0x0102 => 0xC3,
		0x0103 => 0xE3,
		0x0104 => 0xA1,
		0x0105 => 0xB1,
		0x0106 => 0xC6,
		0x0107 => 0xE6,
		0x010C => 0xC8,
		0x010D => 0xE8,
		0x010E => 0xCF,
		0x010F => 0xEF,
		0x0110 => 0xD0,
		0x0111 => 0xF0,
		0x0118 => 0xCA,
		0x0119 => 0xEA,
		0x011A => 0xCC,
		0x011B => 0xEC,
		0x0139 => 0xC5,
		0x013A => 0xE5,
		0x013D => 0xA5,
		0x013E => 0xB5,
		0x0141 => 0xA3,
		0x0142 => 0xB3,
		0x0143 => 0xD1,
		0x0144 => 0xF1,
		0x0147 => 0xD2,
		0x0148 => 0xF2,
		0x0150 => 0xD5,
		0x0151 => 0xF5,
		0x0154 => 0xC0,
		0x0155 => 0xE0,
		0x0158 => 0xD8,
		0x0159 => 0xF8,
		0x015A => 0xA6,
		0x015B => 0xB6,
		0x015E => 0xAA,
		0x015F => 0xBA,
		0x0160 => 0xA9,
		0x0161 => 0xB9,
		0x0162 => 0xDE,
		0x0163 => 0xFE,
		0x0164 => 0xAB,
		0x0165 => 0xBB,
		0x016E => 0xD9,
		0x016F => 0xF9,
		0x0170 => 0xDB,
		0x0171 => 0xFB,
		0x0179 => 0xAC,
		0x017A => 0xBC,
		0x017B => 0xAF,
		0x017C => 0xBF,
		0x017D => 0xAE,
		0x017E => 0xBE,
		0x02C7 => 0xB7,
		0x02D8 => 0xA2,
		0x02D9 => 0xFF,
		0x02DB => 0xB2,
		0x02DD => 0xBD,
		else => null,
	};
}
